"317 :   public void initModules(
318 :       List<JSSourceFile> externs, List<JSModule> modules,
319 :       CompilerOptions options) {
320 :     initOptions(options);
321 : 
322 :     checkFirstModule(modules);
323 :     fillEmptyModules(modules);
324 : 
325 :     this.externs = makeCompilerInput(externs, true);
326 : 
327 :     // Generate the module graph, and report any errors in the module
328 :     // specification as errors.
329 :     this.modules = modules;
330 :     if (modules.size() > 1) {
331 :       try {
332 :         this.moduleGraph = new JSModuleGraph(modules);
333 :       } catch (JSModuleGraph.ModuleDependenceException e) {
334 :         // problems with the module format.  Report as an error.  The
335 :         // message gives all details.
336 :         report(JSError.make(MODULE_DEPENDENCY_ERROR,
337 :                 e.getModule().getName(), e.getDependentModule().getName()));
338 :         return;
339 :       }
340 :     } else {
341 :       this.moduleGraph = null;
342 :     }
343 : 
344 :     this.inputs = getAllInputsFromModules(modules);
345 :     initBasedOnOptions();
346 : 
347 :     initInputsByNameMap();
348 :   }"

